window.GLOSSARY = [{"term": "Adjective", "def": "A word that describes a noun, like happy, blue, or tall."}, {"term": "Adverb", "def": "A word that adds detail to a verb, adjective, or another adverb, like quickly or very."}, {"term": "Antonym", "def": "A word with the opposite meaning, like hot and cold."}, {"term": "Article", "def": "a, an, and the - words that introduce nouns."}, {"term": "Auxiliary verb", "def": "A helping verb such as be, have, do, or a modal."}, {"term": "Causative", "def": "A structure like have/get something done, for arranging an action."}, {"term": "Clause", "def": "A group of words with a subject and a verb."}, {"term": "Cleft sentence", "def": "A sentence restructured with It or What to emphasise one part, as in It was Tom who called."}, {"term": "Collocation", "def": "Words that often appear together, like make a decision."}, {"term": "Conditional", "def": "An if-structure that links a condition with a result."}, {"term": "Conjunction", "def": "A word that links words or clauses, like and, but, or because."}, {"term": "Determiner", "def": "A word before a noun such as the, some, my, or this."}, {"term": "Discourse marker", "def": "A word or phrase that organises ideas, like however or therefore."}, {"term": "Gerund", "def": "An -ing form used like a noun, as in Swimming is fun."}, {"term": "Hedging", "def": "Softening a claim to sound less certain, using words like may or seem to."}, {"term": "Infinitive", "def": "to + base verb (to go), or the base verb alone."}, {"term": "Intransitive verb", "def": "A verb that does not take an object, like sleep or arrive."}, {"term": "Inversion", "def": "Swapping the normal subject-verb order for emphasis, as in Never have I seen..."}, {"term": "Modal", "def": "Verbs like can, could, may, must, should, will, and would."}, {"term": "Modal verb", "def": "A helping verb like can, must, or should that adds meaning such as ability or obligation."}, {"term": "Nominalisation", "def": "Turning a verb or adjective into a noun, like decide into decision."}, {"term": "Noun", "def": "A word for a person, place, thing, or idea."}, {"term": "Object", "def": "The person or thing that receives the action of the verb."}, {"term": "Participle", "def": "The -ing form or the past form used in perfect and passive structures."}, {"term": "Passive", "def": "A structure that focuses on the action or the receiver (was written)."}, {"term": "Phrasal verb", "def": "A verb combined with a particle that often changes its meaning, like give up."}, {"term": "Preposition", "def": "A word like in, on, at, by, or for that shows a relationship."}, {"term": "Pronoun", "def": "A word that replaces a noun, like he, she, it, or they."}, {"term": "Register", "def": "The level of formality in language, from very casual to very formal."}, {"term": "Relative clause", "def": "A clause that gives more information about a noun, introduced by who, which, or that."}, {"term": "Stative verb", "def": "A verb describing a state rather than an action, like know or believe, rarely used in continuous forms."}, {"term": "Subject", "def": "Who or what does the action in a sentence."}, {"term": "Subjunctive", "def": "A verb form used after wish, if only, and suggest that for hypothetical ideas."}, {"term": "Synonym", "def": "A word with a similar meaning to another word."}, {"term": "Tense", "def": "The form of the verb that shows time."}, {"term": "Transitive verb", "def": "A verb that takes an object, like read a book."}];
